// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// Diamond loupe. ContractName=Diamond misses the swap facet unless we keep siblings.
/// This venue is a pass-through router — still cool. Fixture only — not a finding.
contract Diamond {
    mapping(bytes4 => address) public facets;
    fallback() external payable {
        address f = facets[msg.sig];
        assembly { let ok := delegatecall(gas(), f, 0, calldatasize(), 0, 0) }
    }
    function diamondCut(address facet, bytes4[] calldata selectors) external {
        for (uint256 i = 0; i < selectors.length; i++) { facets[selectors[i]] = facet; }
    }
    function facetAddresses() external view returns (address[] memory) {
        address[] memory out; return out;
    }
}

