// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// LiFi / aggregator-shaped diamond facet. Pass-through — not reserves.
contract SwapFacet {
    function exactInput(bytes calldata path, uint256 amountIn) external payable returns (uint256) {
        path; return amountIn;
    }
    function exactInputSingle(address tokenIn, address tokenOut, uint256 amountIn) external payable returns (uint256) {
        tokenIn; tokenOut; return amountIn;
    }
    function swapTokensGeneric(address from, address to, uint256 amount) external { from; to; amount; }
}
